import androidx.navigation.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.material3.*
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.clickable
import androidx.lifecycle.viewmodel.compose.viewModel

// 1. Navigation constants
object NavigationConstants {
    const val HOME = "home"
    const val TASK_DETAIL = "task_detail"
    const val SETTINGS = "settings"
    const val TASK_DETAIL_ARG = "taskId"
}

// 2. Extension function for home screen
fun NavGraphBuilder.homeScreen(navController: NavController) {
    composable(NavigationConstants.HOME) {
        val tasks = listOf(
            Task(id = 1, title = "Tâche 1"),
            Task(id = 2, title = "Tâche 2")
        )

        Column(modifier = Modifier.padding(16.dp)) {
            Text("Liste des tâches", style = MaterialTheme.typography.h5)
            Spacer(modifier = Modifier.height(16.dp))

            tasks.forEach { task ->
                Card(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(8.dp)
                        .clickable {
                            navController.navigate("${NavigationConstants.TASK_DETAIL}/${task.id}")
                        }
                ) {
                    Text(task.title, modifier = Modifier.padding(16.dp))
                }
            }
        }
    }
}

// 3. Extension function for task detail screen with argument
fun NavGraphBuilder.taskDetailScreen(navController: NavController) {
    composable(
        "${NavigationConstants.TASK_DETAIL}/{${NavigationConstants.TASK_DETAIL_ARG}}",
        arguments = listOf(
            navArgument(NavigationConstants.TASK_DETAIL_ARG) { type = NavType.LongType }
        )
    ) { backStackEntry ->
        val taskId = backStackEntry.arguments?.getLong(NavigationConstants.TASK_DETAIL_ARG)
        TaskDetailScreen(taskId = taskId ?: 0L)
    }
}

// Task data class
data class Task(
    val id: Long,
    val title: String,
    val description: String = ""
)

// Task detail screen composable
@Composable
fun TaskDetailScreen(
    taskId: Long,
    viewModel: TaskDetailViewModel = viewModel()
) {
    val state = viewModel.getStateForTask(taskId)

    Column(modifier = Modifier.padding(16.dp)) {
        Text("Détail de la tâche $taskId", style = MaterialTheme.typography.h5)
        Spacer(modifier = Modifier.height(16.dp))

        if (state != null) {
            Text("Titre: ${state.title}")
            Spacer(modifier = Modifier.height(8.dp))
            Text("Description: ${state.description}")
            Spacer(modifier = Modifier.height(8.dp))
            Text("Complétée: ${state.isCompleted}")
        } else {
            Text("Tâche non trouvée")
        }
    }
}

// Task detail ViewModel
class TaskDetailViewModel : ViewModel() {
    private val _taskStates = mutableStateMapOf<Long, Task>()

    fun getStateForTask(taskId: Long): Task? = _taskStates[taskId]

    fun updateTaskState(task: Task) {
        _taskStates[task.id] = task
    }
}

// 4 & 5. AppNavigation with NavHost
@Composable
fun AppNavigation() {
    val navController = rememberNavController()

    NavHost(
        navController = navController,
        startDestination = NavigationConstants.HOME
    ) {
        homeScreen(navController)
        taskDetailScreen(navController)
    }
}

